.home-workout{min-height:238px;margin:0 0 15px;border-radius:19px}.home-workout>img{object-position:center 23%}.home-workout:after{background:linear-gradient(0deg,#08140ff7 0%,#091710b8 43%,#09171012 100%)}.home-session-status{position:absolute;top:14px;left:15px;z-index:1;font-size:8px;font-weight:750;letter-spacing:1.1px;color:#e9fff1;background:#122c23ab;padding:7px 9px;border:1px solid #a6d8b52b;border-radius:20px;backdrop-filter:blur(6px)}.home-workout .workout-feature-shade{bottom:15px;left:16px;right:16px}.home-workout h2{font-size:25px;font-weight:750;color:white;letter-spacing:-.7px;margin:0 0 7px}.home-workout p{font-size:11px;color:#ccdcd1;margin:0 0 15px}.home-workout-actions{display:flex;gap:8px}.home-workout-actions>.primary{display:flex;flex:1;align-items:center;justify-content:space-between;gap:8px;min-height:46px;font-size:12px;padding:12px 14px;border-radius:11px}.home-workout-actions svg{height:18px;width:18px;flex:none}.home-change-workout{display:flex;flex-direction:column;align-items:center;justify-content:center;gap:3px;width:64px;flex:none;min-height:46px;border:1px solid #ffffff38;background:#ffffff13;color:#e4eee8;border-radius:11px;padding:6px}.home-change-workout span{font-size:8px;font-weight:500}.home-session-progress{margin:-4px 0 12px}.home-session-progress>span{font-size:9px;color:#adceba;display:block;margin-bottom:6px}.home-session-progress progress{width:100%;height:4px;accent-color:#4dd68f;display:block}
.home-nutrition{background:white;border:1px solid #e5ede6;border-radius:17px;padding:16px;margin-bottom:13px;box-shadow:0 3px 10px #17351f03}.home-nutrition h3{display:flex;align-items:center;gap:8px;font-size:13px;color:#344e3d}.home-nutrition h3 svg{width:17px;height:17px;color:#50a475;flex:none}.home-text-link{display:inline-flex;align-items:center;gap:5px;width:auto;min-height:44px;padding:4px 0;border:0;background:none;color:#228b54;font-size:10px;font-weight:650}.home-text-link svg{width:14px;height:14px}.home-calorie-line{display:flex;justify-content:space-between;align-items:baseline;gap:8px;margin:10px 0 11px}.home-calorie-line>strong{font-size:28px;letter-spacing:-1px;color:#203b2a;font-weight:800;line-height:1.15}.home-calorie-line>strong>small{font-size:10px;font-weight:450;letter-spacing:0;color:#91a195}.home-calorie-line>span{font-size:9px;color:#98a69b;white-space:nowrap}.home-calorie-progress{display:block;width:100%;height:7px;border-radius:9px;overflow:hidden;appearance:none;border:0;background:#edf3ee}.home-calorie-progress::-webkit-progress-bar{background:#edf3ee}.home-calorie-progress::-webkit-progress-value{background:#16b76a;border-radius:9px}.home-calorie-progress::-moz-progress-bar{background:#16b76a;border-radius:9px}.home-macro-row{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:11px;margin:16px 0}.home-macro-row>div{min-width:0}.home-macro-row>div>span{display:block;font-size:9px;color:#7f9587;margin-bottom:5px}.home-macro-row strong{display:block;font-size:14px;color:#518369;letter-spacing:-.3px}.home-macro-row strong small{font-size:9px;letter-spacing:0;font-weight:400;color:#9ca99f}.home-macro-row progress{display:block;width:100%;height:4px;margin-top:8px;accent-color:#6cba8c}.home-macro-row>div:nth-child(2) strong{color:#b2954a}.home-macro-row>div:nth-child(2) progress{accent-color:#d5bd73}.home-macro-row>div:nth-child(3) strong{color:#6b96b9}.home-macro-row>div:nth-child(3) progress{accent-color:#8fb4d2}.home-nutrition-bottom{display:flex;align-items:center;justify-content:space-between;border-top:1px solid #eef3ef;padding-top:4px}.home-nutrition-bottom>small{font-size:10px;color:#7f9787}
.home-week-card{display:block;width:100%;text-align:left;background:white;border:1px solid #e6ede7;border-radius:17px;padding:16px;margin:0 0 13px}.home-week-card h3{font-size:14px;color:#36503f}.home-week-card .row>strong{font-size:18px;color:#24995c;letter-spacing:-.5px}.home-week-card .row>strong>small{font-size:10px;color:#8fa294;font-weight:400;letter-spacing:0}.home-week-meter{height:5px;border-radius:9px;background:#edf3ee;margin:12px 0 15px;overflow:hidden}.home-week-meter>span{display:block;height:100%;border-radius:9px;background:#16b76a}.home-week-days{display:grid;grid-template-columns:repeat(7,minmax(0,1fr));gap:5px;text-align:center}.home-week-days>div>span{display:grid;place-items:center;width:26px;height:26px;border-radius:50%;border:1px solid #e1e9e3;background:#f9fbf9;margin:0 auto 5px;color:#cbd8cf}.home-week-days>div>span.is-today{border:1.5px solid #29b26b;background:#ecfaf2}.home-week-days>div>span.is-done{background:#16b76a;border-color:#16b76a;color:white}.home-week-days svg{width:13px;height:13px}.home-week-days small{font-size:9px;color:#9cad9f;font-weight:500}.home-week-footer{display:flex;align-items:center;justify-content:space-between;border-top:1px solid #eef3ef;padding-top:10px;margin-top:12px}.home-week-footer>small{font-size:9px;font-weight:400;color:#9cad9f}.home-week-footer>span{display:flex;align-items:center;gap:5px;font-size:9px;color:#4a9e6c}.home-week-footer svg{width:13px;height:13px}
.home-shortcuts{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px}.home-shortcut{position:relative;display:flex;flex-direction:column;align-items:flex-start;text-align:left;min-width:0;min-height:143px;padding:14px 13px;border:1px solid #e5ece6;background:white;border-radius:16px}.home-shortcut>svg{width:20px;height:20px;color:#5aab7d;margin-bottom:9px}.home-shortcut:nth-child(2)>svg{color:#b5a05b}.home-shortcut-label{font-size:10px;color:#879d8e;font-weight:500}.home-shortcut>strong{font-size:17px;letter-spacing:-.5px;color:#2d4936;margin-top:6px;line-height:1.3}.home-shortcut>strong>small{font-size:10px;font-weight:400;letter-spacing:0}.home-shortcut-note{font-size:10px;color:#a0aea3;font-weight:400;margin-top:6px;line-height:1.4}.home-shortcut-arrow{position:absolute;top:16px;right:13px;color:#b7c9bc}.home-shortcut-arrow svg{width:14px;height:14px}.home-edit-plan{display:flex;align-items:center;justify-content:center;gap:7px;margin:12px 0 0;min-height:44px;border:0;background:none;color:#96a69a;font-size:10px;font-weight:500}.home-edit-plan svg{width:14px;height:14px}
@media(max-width:360px){.home-workout{min-height:229px}.home-workout h2{font-size:23px}.home-nutrition,.home-week-card{padding:14px}.home-calorie-line>strong{font-size:25px}.home-calorie-line>strong>small{font-size:9px}.home-day-badge{font-size:9px}.home-shortcut{padding:13px 11px}.home-shortcut>strong{font-size:15px}.home-macro-row{gap:8px}.home-macro-row strong small{font-size:9px}}
